$('#detail-title').textContent=title;$('#detail-kicker').textContent=kicker;$('#detail-body').innerHTML=body;if(!$('#detail').open)$('#detail').showModal();$('#detail-body').scrollTop=0;icons();if(type==='memory')loadMemory(a);if(type==='routine')loadRuns(data);if(type==='audit')loadAudit();
